{
  "apiVersion": 1,
  "type": "component.detail.props",
  "package": "@astryxdesign/lab",
  "data": [
    {
      "name": "label",
      "type": "string",
      "description": "Metric name shown above the value, e.g. \"Total requests\".",
      "required": true
    },
    {
      "name": "value",
      "type": "ReactNode",
      "description": "Headline metric rendered large with tabular numerals. Pass a pre-formatted string like \"1.2M\".",
      "required": true
    },
    {
      "name": "delta",
      "type": "{value: string, direction: 'up' | 'down' | 'flat', sentiment?: 'positive' | 'negative' | 'neutral'}",
      "description": "Change indicator next to the value: an up/down/flat glyph plus colored text. sentiment overrides the direction color mapping (up=positive, down=negative, flat=neutral) for inverted metrics like error rate."
    },
    {
      "name": "description",
      "type": "string",
      "description": "Muted supporting line under the value, e.g. \"vs. previous 30 days\"."
    },
    {
      "name": "media",
      "type": "ReactNode",
      "description": "Trend slot rendered below the text content, e.g. a sparkline or mini chart. Stat does not render a chart itself."
    },
    {
      "name": "size",
      "type": "'sm' | 'md' | 'lg'",
      "description": "Size variant controlling the value's font size.",
      "default": "'md'"
    },
    {
      "name": "xstyle",
      "type": "StyleXStyles",
      "description": "StyleX styles for layout customization (margins, positioning, sizing). Must be a stylex.create() value, not an inline style object like style={{}}."
    }
  ],
  "meta": {
    "answeredBy": {
      "cli": "0.7.12",
      "core": "0.7.12",
      "copy": "starting"
    }
  }
}
